// WhatsApp-style animated typing dots. Three bouncing circles in a wave.
function TypingDots({ color = '#888', size = 5 }) {
  const a1 = useRef(new Animated.Value(0)).current;
  const a2 = useRef(new Animated.Value(0)).current;
  const a3 = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    // Why (vidiante polish): the dots used to bounce 4px with a linear feel.
    // Now they ride a sine wave with bigger amplitude (-7px) and pop scale
    // 1→1.25 at the peak, stagger 110ms instead of 150ms — reads as a more
    // natural, "alive" wave (matches iMessage/Telegram), not three blinking
    // pixels. Slightly larger size (4→5) so it's visible at glance distance.
    const nd = Platform.OS !== 'web';
    const loop = (v, delay) => Animated.loop(
      Animated.sequence([
        Animated.delay(delay),
        Animated.timing(v, { toValue: 1, duration: 320, easing: Easing.inOut(Easing.sin), useNativeDriver: nd }),
        Animated.timing(v, { toValue: 0, duration: 320, easing: Easing.inOut(Easing.sin), useNativeDriver: nd }),
      ])
    );
    const animations = [loop(a1, 0), loop(a2, 110), loop(a3, 220)];
    animations.forEach(x => x.start());
    return () => animations.forEach(x => x.stop());
  }, [a1, a2, a3]);
  const dotStyle = { width: size, height: size, borderRadius: size / 2, backgroundColor: color };
  const wave = (v) => ({
    transform: [
      { translateY: v.interpolate({ inputRange: [0, 1], outputRange: [0, -7] }) },
      { scale: v.interpolate({ inputRange: [0, 1], outputRange: [1, 1.25] }) },
    ],
    opacity: v.interpolate({ inputRange: [0, 1], outputRange: [0.55, 1] }),
  });
  return (
    <View style={{ flexDirection: 'row', gap: 4, alignItems: 'center', height: 14 }}>
      <Animated.View style={[dotStyle, wave(a1)]} />
      <Animated.View style={[dotStyle, wave(a2)]} />
      <Animated.View style={[dotStyle, wave(a3)]} />
    </View>
  );
}

// Cross-fades the chat header subtitle ("online" / "digitando..." / last-seen)
// when the value changes. Without this the text instant-swaps and feels
// jarring on every state change. iMessage/Telegram both use a soft fade.
// [2026-10-08 chat-beauty-chrome] Real cross-fade: the old line fades OUT and
// drifts up 3pt, the new one fades IN from 3pt below (iOS nav-bar subtitle
// feel). Interrupted transitions (online → digitando → online in <300ms) no
// longer strand a stale label: the latest `text` always lands.
function PresenceTextFade({ text, style }) {
  const [displayed, setDisplayed] = React.useState(text);
  const opacity = useRef(new Animated.Value(1)).current;
  const shift = useRef(new Animated.Value(0)).current;
  const latestRef = useRef(text);
  latestRef.current = text;
  useEffect(() => {
    if (text === displayed) return;
    const nd = Platform.OS !== 'web';
    if (isReduceMotionEnabled()) { setDisplayed(text); opacity.setValue(1); shift.setValue(0); return; }
    Animated.parallel([
      Animated.timing(opacity, { toValue: 0, duration: 110, easing: Easing.in(Easing.quad), useNativeDriver: nd }),
      Animated.timing(shift, { toValue: -3, duration: 110, easing: Easing.in(Easing.quad), useNativeDriver: nd }),
    ]).start(() => {
      setDisplayed(latestRef.current);
      shift.setValue(3);
      Animated.parallel([
        Animated.timing(opacity, { toValue: 1, duration: 190, easing: Easing.out(Easing.cubic), useNativeDriver: nd }),
        Animated.timing(shift, { toValue: 0, duration: 190, easing: Easing.out(Easing.cubic), useNativeDriver: nd }),
      ]).start();
    });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text]);
  return (
    <Animated.Text style={[style, { opacity, transform: [{ translateY: shift }] }]} numberOfLines={1}>{displayed}</Animated.Text>
  );
}

// Wrapper that keeps TypingDots mounted briefly with an opacity fade when
// `visible` flips false. Without this the dots vanished instantly when the
// peer stopped typing — felt twitchy compared to WhatsApp's smooth fade.
function TypingDotsFade({ visible, color }) {
  const [mounted, setMounted] = useState(visible);
  const opacity = useRef(new Animated.Value(visible ? 1 : 0)).current;
  useEffect(() => {
    if (visible) {
      if (!mounted) setMounted(true);
      Animated.timing(opacity, { toValue: 1, duration: 160, useNativeDriver: Platform.OS !== 'web' }).start();
    } else {
      Animated.timing(opacity, { toValue: 0, duration: 220, useNativeDriver: Platform.OS !== 'web' }).start(({ finished }) => {
        if (finished) setMounted(false);
      });
    }
  }, [visible, mounted, opacity]);
  if (!mounted) return null;
  return (
    <Animated.View style={{ opacity }}>
      <TypingDots color={color} />
    </Animated.View>
  );
}

// Header subtitle presence pip — the small dot next to "online"/"visto por
// último". Two upgrades over the old static <View>:
//   1. When ONLINE it PULSES — a green halo scales 1→2.6 behind the dot, the
//      same living cue the avatar's PresencePulse and the chat-list dot use,
//      so the header matches the rest of the app.
//   2. It stays MOUNTED across the online↔offline transition and cross-fades
//      colour/opacity (green ↔ muted grey) instead of popping in/out — mirrors
//      the TypingDotsFade fade pattern so the whole presence line settles
//      together. `online` here means "live online" (peer online AND our socket
//      up); anything else renders the muted grey dot. While typing the pip is
//      faded out (typing has its own animated dots beside the text).
function HeaderPresencePip({ online, dimmedOnline, hidden }) {
  const ringScale = useRef(new Animated.Value(1)).current;
  const ringOpacity = useRef(new Animated.Value(0)).current;
  // Cross-fade target colour for the solid dot (green when live, grey when
  // socket down). Driven via a 0→1 progress value so we can interpolate.
  const colorProg = useRef(new Animated.Value(online ? 1 : 0)).current;
  const wrapOpacity = useRef(new Animated.Value(hidden ? 0 : 1)).current;

  // Fade the whole pip in/out (typing hides it) without unmounting.
  useEffect(() => {
    Animated.timing(wrapOpacity, {
      toValue: hidden ? 0 : 1,
      duration: hidden ? 180 : 200,
      useNativeDriver: Platform.OS !== 'web',
    }).start();
  }, [hidden, wrapOpacity]);

  // Smoothly transition the dot colour on the online↔offline (grey) flip.
  useEffect(() => {
    Animated.timing(colorProg, {
      toValue: online ? 1 : 0,
      duration: 260,
      // colour interpolation can't use the native driver.
      useNativeDriver: false,
    }).start();
  }, [online, colorProg]);

  // Pulse the halo only while live-online (and not hidden). Loop scales the
  // ring 1→2.6 + fades it out, like the list/avatar dots. Native driver.
  useEffect(() => {
    let loop;
    const active = online && !hidden;
    if (active) {
      ringScale.setValue(1);
      ringOpacity.setValue(0.45);
      loop = Animated.loop(
        Animated.parallel([
          Animated.sequence([
            Animated.timing(ringScale, { toValue: 2.6, duration: 1800, easing: Easing.out(Easing.quad), useNativeDriver: Platform.OS !== 'web' }),
            Animated.timing(ringScale, { toValue: 1, duration: 0, useNativeDriver: Platform.OS !== 'web' }),
          ]),
          Animated.sequence([
            Animated.timing(ringOpacity, { toValue: 0, duration: 1800, useNativeDriver: Platform.OS !== 'web' }),
            Animated.timing(ringOpacity, { toValue: 0.45, duration: 0, useNativeDriver: Platform.OS !== 'web' }),
          ]),
        ])
      );
      loop.start();
    } else {
      ringOpacity.setValue(0);
    }
    return () => { try { loop?.stop?.(); } catch {} };
  }, [online, hidden, ringScale, ringOpacity]);

  const dotColor = colorProg.interpolate({
    inputRange: [0, 1],
    outputRange: ['rgba(255,255,255,0.45)', dimmedOnline ? 'rgba(255,255,255,0.45)' : '#4ade80'],
  });

  return (
    <Animated.View style={{ width: 7, height: 7, alignItems: 'center', justifyContent: 'center', opacity: wrapOpacity }}>
      {/* Pulsing halo (only visible while live-online) */}
      <Animated.View
        pointerEvents="none"
        style={{
          position: 'absolute',
          width: 7, height: 7, borderRadius: 3.5,
          backgroundColor: '#4ade80',
          opacity: ringOpacity,
          transform: [{ scale: ringScale }],
        }}
      />
      {/* Solid dot — colour cross-fades green↔grey on the presence flip */}
      <Animated.View
        style={{
          width: 7, height: 7, borderRadius: 3.5,
          backgroundColor: dotColor,
          ...(Platform.OS === 'web' && online && !dimmedOnline ? { boxShadow: '0 0 6px rgba(74, 222, 128, 0.6)' } : {}),
        }}
      />
    </Animated.View>
  );
}

// [2026-10-06 thread-tech] Memoized JSON.parse for per-bubble payloads.
// renderMessage parsed the same strings on EVERY row render (image_variants
// 5x per image bubble, call/meetup/playlist/voicemail content, meta). Rows
// re-render on every overlay/selection/receipt change, so this was ~25
// parses per bubble render. Bounded Map keyed by the source string (string
