// ============================================================
// SAFE ALERT (works on web + native)
// ============================================================
function safeAlert(title, message, buttons) {
  if (Platform.OS === 'web') {
    if (buttons && buttons.length > 0) {
      // Find destructive/OK button and cancel button
      const cancelBtn = buttons.find(b => b.style === 'cancel');
      const actionBtn = buttons.find(b => b.style !== 'cancel') || buttons[0];
      const confirmed = window.confirm(`${title}\n\n${message || ''}`);
      if (confirmed && actionBtn?.onPress) actionBtn.onPress();
      else if (!confirmed && cancelBtn?.onPress) cancelBtn.onPress();
    } else {
      try { window.alert(message || title); } catch {}
    }
  } else {
    try { Alert.alert(title, message, buttons); } catch {}
  }
}

// ============================================================
// AUDIO RECORDER
// ============================================================

// [2026-10-06 UX2] holdMode: null (tap-to-record) | 'hold' (finger on the mic,
// rendered as a compact overlay pill) | 'locked' (hands-free controls).
// holdCtlRef receives { move, cancel, lock, release } so the composer's mic
// gesture can drive this recorder without re-rendering per touch move.
function AudioRecorder({ onSend, onCancel, colors, t, conversationId, holdMode = null, holdCtlRef = null, onShortHold }) {
  const [recording, setRecording] = useState(null);
  const [duration, setDuration] = useState(0);
  const [error, setError] = useState(null);
  const [waveformLevels, setWaveformLevels] = useState([]);
  // View-once toggle — when on, the recipient can listen exactly once before
  // the audio is consumed (WhatsApp 2026-Q1 parity). Visual: small "1" pill
  // above the mic, purple when active + hint text "Áudio só pode ser ouvido
  // uma vez". Pre-upload session is skipped when active so view_once=1 lands
  // on chat_upload, which is the path that propagates the flag to the row.
  const [voiceViewOnce, setVoiceViewOnce] = useState(false);
  // Preview state — set after stopping (to listen before sending, WhatsApp-style)
  const [previewData, setPreviewData] = useState(null); // { uri, blob?, name, type, duration, waveform, voiceSessionId? }
  const [previewPlaying, setPreviewPlaying] = useState(false);
  const [previewProgress, setPreviewProgress] = useState(0); // 0..1
  const previewAudioRef = useRef(null); // HTMLAudioElement on web, expo-audio player on native
  const previewIntervalRef = useRef(null);
  // Slide-to-cancel (horizontal) — slideX drives the cancel hint fade + pill
  // recoil. (The vertical slide-up-to-lock gesture was removed: this recorder
  // is tap-to-record/hands-free, so a "lock" affordance is meaningless. Cancel
  // is always available via the explicit X button.)
  const slideX = useRef(new Animated.Value(0)).current;
  const slideHapticRef = useRef(false);
  const cancelledRef = useRef(false);
  const intervalRef = useRef(null);
  const startTimeRef = useRef(0);
  const mediaRecorderRef = useRef(null);
  const chunksRef = useRef([]);
  const mountedRef = useRef(true);
  const analyserRef = useRef(null);
  const audioCtxRef = useRef(null);
  const waveIntervalRef = useRef(null);
  const pulseAnim = useRef(new Animated.Value(1)).current;
  const pulseLoopRef = useRef(null);
  // When the user taps "Send" on the recorder pill we want to skip the manual
  // preview step and ship the audio straight away — WhatsApp parity.
  // handleStop always lands the captured audio in `previewData`; this flag lets
  // a one-shot effect auto-confirm the send the moment that data is ready, so
  // we reuse the whole stop/drain/finalize pipeline without duplicating it.
  const pendingDirectSendRef = useRef(false);
  // Voice pre-upload session state. While recording on web, we ship each
  // dataavailable chunk to the server in order so the file is mostly there
  // by the time the user releases. If anything in this pipeline fails
  // (network blip, server cold path), we transparently fall back to the
  // legacy single-shot upload in handleSendAudio — never block the user.
  const voiceSessionRef = useRef(null);    // { sessionId, nextChunkIndex, mime, alive }
  const voiceUploadQueue = useRef([]);     // ordered chunk Blobs awaiting upload
  const voiceUploadInflight = useRef(false);
  // Voice draft persistence — see comment above startTimer. The persist
  // interval is cleared in stop/cancel/unmount.
  const voiceDraftPersistRef = useRef(null);
  const voiceDraftUriRef = useRef(null);
  // [2026-10-06 UX2] Leak guards + hold-to-record plumbing.
  // recordingRef mirrors `recording` so the unmount / AppState handlers (stale
  // closures) can always reach the live recorder and release the mic.
  const recordingRef = useRef(null);
  const holdModeRef = useRef(holdMode);
  holdModeRef.current = holdMode;
  const latestRef = useRef({});
  const [holdTrashing, setHoldTrashing] = useState(false);
  const trashAnim = useRef(new Animated.Value(0)).current;
  useEffect(() => { recordingRef.current = recording; }, [recording]);
  // [2026-10-07 voice-native] Live input level (0..1) for the UI-thread meter:
  // native recorder → sync JSI read of its 30 Hz meter; expo-audio fallback →
  // status.metering (dBFS, -50..0 → 0..1, same curve as the native modules).
  const getLiveLevel = useCallback(() => {
    const r = recordingRef.current;
    if (!r || r === 'web') return 0;
    if (r.__native) {
      try { return Number(r.NativeAudio?.currentLevelSync?.()) || 0; } catch { return 0; }
    }
    try {
      const db = Number(r.getStatus?.()?.metering);
      if (isFinite(db)) return Math.max(0, Math.min(1, (db + 50) / 50));
    } catch {}
    return 0;
  }, []);

  useEffect(() => {
    mountedRef.current = true;
    startRecording();
    // Start pulsing animation for the red dot
    pulseLoopRef.current = Animated.loop(
      Animated.sequence([
        Animated.timing(pulseAnim, { toValue: 1.6, duration: 600, useNativeDriver: true }),
        Animated.timing(pulseAnim, { toValue: 1, duration: 600, useNativeDriver: true }),
      ])
    );
    pulseLoopRef.current.start();
    return () => {
      mountedRef.current = false;
      if (pulseLoopRef.current) pulseLoopRef.current.stop();
      if (intervalRef.current) clearInterval(intervalRef.current);
      if (waveIntervalRef.current) clearInterval(waveIntervalRef.current);
      if (voiceDraftPersistRef.current) { clearInterval(voiceDraftPersistRef.current); voiceDraftPersistRef.current = null; }
      // Tear down the preview player on unmount so navigating away mid-preview
      // doesn't leave the AVAudioSession grabbed (Spotify stays paused). Inline
      // teardown — teardownPreviewPlayer is defined later in the component but
      // is captured by the time this cleanup runs.
      if (previewIntervalRef.current) { clearInterval(previewIntervalRef.current); previewIntervalRef.current = null; }
      const _pp = previewAudioRef.current;
      if (_pp) {
        if (Platform.OS === 'web') {
          try { _pp.pause?.(); } catch {}
        } else {
          try { _pp._previewSub?.remove?.(); } catch {}
          try { _pp.pause?.(); } catch {}
          try { _pp.remove?.(); } catch {}
          try {
            const { setAudioModeAsync } = require('expo-audio');
            setAudioModeAsync?.({ interruptionMode: 'mixWithOthers', interruptionModeAndroid: 'mixWithOthers' }).catch(() => {});
          } catch {}
        }
        previewAudioRef.current = null;
      }
      if (Platform.OS === 'web') {
        try {
          const mr = mediaRecorderRef.current;
          if (mr && mr.state !== 'inactive') mr.stop();
          if (mr?.stream) mr.stream.getTracks().forEach(t => t.stop());
        } catch {}
        try { audioCtxRef.current?.close(); } catch {}
      }
      // [2026-10-06 UX2] Native leak fix: unmounting mid-recording (navigate
      // away, ErrorBoundary reset, hold released before stop) used to leave
      // the native recorder running with the mic + allowsRecording session
      // grabbed. handleStop/handleCancel null the ref themselves, so this
      // only fires for a recorder nobody stopped.
      const _rec = recordingRef.current;
      recordingRef.current = null;
      if (Platform.OS !== 'web' && _rec && _rec !== 'web') {
        Promise.resolve()
          .then(() => (_rec.__native && _rec.NativeAudio?.cancelRecording) ? _rec.NativeAudio.cancelRecording() : _rec.stop?.())
          .catch(() => {})
          .then(() => { try { return require('expo-audio').setAudioModeAsync({ allowsRecording: false }); } catch {} })
          .catch(() => {});
      }
      if (voiceSessionRef.current) { voiceSessionRef.current.alive = false; }
      if (holdCtlRef) holdCtlRef.current = null;
    };
  }, []);

  // [2026-10-06 UX2] App goes to background: a held recording can't survive
  // (the touch is gone) → cancel it. Hands-free/locked recording is stopped
  // into the preview (keeps the audio, releases the mic) instead of silently
  // recording in background.
  useEffect(() => {
    if (Platform.OS === 'web') return undefined;
    const sub = AppState.addEventListener('change', (st) => {
      const L = latestRef.current;
      if (holdModeRef.current === 'hold' && (st === 'background' || st === 'inactive')) {
        try { L.handleCancel?.(); } catch {}
        return;
      }
      if (st === 'background' && recordingRef.current) {
        try { L.handleStop?.(); } catch {}
      }
    });
    return () => { try { sub?.remove?.(); } catch {} };
  }, []);

  // Direct-send: handleStop assembles the audio into `previewData`; if the user
  // asked to send straight away (tapped Send on the recorder pill) we confirm
  // the send as soon as that data lands. Guarded by
  // the ref so the normal Stop→preview flow is untouched.
  useEffect(() => {
    if (previewData && pendingDirectSendRef.current) {
      pendingDirectSendRef.current = false;
      handleConfirmSend();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [previewData]);

  // Serial drain — uploads chunks one-at-a-time in the order they arrived
  // so the server's strict in-order assemblage holds. If a chunk POST fails
  // we kill the session (alive=false) and the legacy fallback takes over.
  const drainVoiceUploadQueue = async () => {
    if (voiceUploadInflight.current) return;
    if (!voiceSessionRef.current?.alive) return;
    if (voiceUploadQueue.current.length === 0) return;
    voiceUploadInflight.current = true;
    try {
      while (
        mountedRef.current &&
        voiceSessionRef.current?.alive &&
        voiceUploadQueue.current.length > 0
      ) {
        const blob = voiceUploadQueue.current.shift();
        const idx = voiceSessionRef.current.nextChunkIndex;
        try {
          const r = await api.chatVoiceSessionChunk(voiceSessionRef.current.sessionId, idx, blob);
          if (!r?.success) {
            voiceSessionRef.current.alive = false;
            break;
          }
          voiceSessionRef.current.nextChunkIndex = idx + 1;
        } catch {
          if (voiceSessionRef.current) voiceSessionRef.current.alive = false;
          break;
        }
      }
    } finally {
      voiceUploadInflight.current = false;
    }
  };

  const startTimer = () => {
    startTimeRef.current = Date.now();
    intervalRef.current = setInterval(() => {
      if (!mountedRef.current) return;
      const d = Math.floor((Date.now() - startTimeRef.current) / 1000);
      setDuration(d);
      // Auto-stop at 5min — server caps audio uploads at this length and
      // without the auto-stop the recording silently fails on send. WhatsApp
      // pattern: stop and present preview so user can send what they got.
      if (d >= 300) {
        // [2026-10-06 UX2] go through latestRef — this interval's closure is
        // from the render where `recording` was still null, so calling
        // handleStop directly was a no-op. While held, ship it (the overlay
        // preview isn't interactive).
        const L = latestRef.current || {};
        try { (holdModeRef.current === 'hold' ? L.handleStopAndSend : L.handleStop)?.(); } catch {}
      }
    }, 1000);
    // Persist a recording-in-progress draft every 500ms so that if the app
    // crashes or the user backgrounds + force-quits mid-record, we can offer
    // to restore the audio they had so far on the next open. The "uri" field
    // is populated once a stop has produced a blob/file; during live recording
    // we still save duration + waveform so the recovery prompt knows there
    // was an in-flight session.
    voiceDraftPersistRef.current = setInterval(async () => {
      if (!mountedRef.current || !conversationId) return;
      try {
        const AsyncStorage = require('@react-native-async-storage/async-storage').default;
        const d = Math.floor((Date.now() - startTimeRef.current) / 1000);
        await AsyncStorage.setItem(
          'voice_draft:' + conversationId,
          JSON.stringify({ uri: voiceDraftUriRef.current || null, duration: d, waveform: waveformLevels.slice(-60) })
        );
      } catch {}
    }, 500);
  };

  const startRecording = async () => {
    // [2026-10-07 voice-native] recording always pauses a playing voice note.
    try { VoiceNote.pauseVoiceNote(); } catch {}
    try {
      if (Platform.OS === 'web') {
        // Check browser support
        if (typeof navigator === 'undefined' || !navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
          setError(t('chatConv.audioNotSupported'));
          return;
        }
        if (typeof MediaRecorder === 'undefined') {
          setError(t('chatConv.mediaRecorderUnavailable'));
          return;
        }
        let stream;
        try {
          stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        } catch (e) {
          if (e.name === 'NotAllowedError') {
            setError(t('chatConv.micPermissionDenied'));
          } else if (e.name === 'NotFoundError') {
            setError(t('chatConv.micNotFound'));
          } else {
            setError(t('chatConv.micAccessError'));
          }
          return;
        }
        if (!mountedRef.current) { stream.getTracks().forEach(t => t.stop()); return; }

        const mimeType = typeof MediaRecorder.isTypeSupported === 'function' && MediaRecorder.isTypeSupported('audio/webm;codecs=opus')
          ? 'audio/webm;codecs=opus'
          : 'audio/webm';
        // [2026-09-23] Voz mono ~32kbps no web também (Opus a 32k é limpo pra fala).
        const mr = new MediaRecorder(stream, { mimeType, audioBitsPerSecond: 32000 });
        chunksRef.current = [];
        // Kick off voice pre-upload session in parallel with recording.
        // The server returns a session_id we'll use for every chunk POST.
        // If start fails (offline, 5xx, rate-limit), we just skip pre-upload
        // and the legacy single-shot path takes over on stop.
        voiceSessionRef.current = null;
        voiceUploadQueue.current = [];
        voiceUploadInflight.current = false;
        api.chatVoiceSessionStart(conversationId).then(r => {
          if (!mountedRef.current) return;
          if (r?.success && r?.data?.session_id) {
            voiceSessionRef.current = {
              sessionId: r.data.session_id,
              nextChunkIndex: 0,
              mime: mimeType,
              alive: true,
            };
            // Drain whatever has accumulated in the queue while we waited.
            drainVoiceUploadQueue();
          }
        }).catch(() => {});
        mr.ondataavailable = (e) => {
          if (!e.data || e.data.size === 0) return;
          chunksRef.current.push(e.data);
          if (voiceSessionRef.current?.alive) {
            voiceUploadQueue.current.push(e.data);
            drainVoiceUploadQueue();
          }
        };
        mr.onerror = () => { if (mountedRef.current) setError(t('chatConv.recordingError')); };
        mr.start(200);
        mediaRecorderRef.current = mr;
        // Set up live waveform via Web Audio API AnalyserNode
        try {
          const actx = new (window.AudioContext || window.webkitAudioContext)();
          const source = actx.createMediaStreamSource(stream);
          const analyser = actx.createAnalyser();
          analyser.fftSize = 256;
          source.connect(analyser);
          audioCtxRef.current = actx;
          analyserRef.current = analyser;
          const dataArray = new Uint8Array(analyser.frequencyBinCount);
          waveIntervalRef.current = setInterval(() => {
            if (!mountedRef.current) return;
            analyser.getByteFrequencyData(dataArray);
            // Sample 30 bars from frequency data
            const bars = [];
            const step = Math.floor(dataArray.length / 30);
            for (let i = 0; i < 30; i++) {
              bars.push(dataArray[i * step] / 255);
            }
            // Push the entire FFT snapshot so the waveform actually reflects the
            // current frequencies instead of inching forward one bar per tick.
            setWaveformLevels(prev => [...prev, ...bars].slice(-60));
          }, 50);
        } catch {}
        setRecording('web');
        startTimer();
        // Notify conversation members that we're recording
        try {
          const tcpClient = require('../services/tcp-client').getTCPClient();
          tcpClient.sendStartedRecording(conversationId);
        } catch {}
        return;
      }

      // Native: use expo-audio
      // [WAVE 39 2026-05-20] BUG 1 — Android white-screen crash on record. Root
      // cause: permission denial or native module crash returned null/undefined
      // URI which then crashed downstream render. Wrap the whole permission +
      // module-load + start sequence in defensive try/catch with explicit
      // Alert.alert fallback (vs silent setError that didn't surface on some
      // Android skins where banner was eaten by the keyboard). On Android,
      // explicitly check RECORD_AUDIO permission BEFORE touching expo-audio.
      let expoAudio;
      try {
        expoAudio = require('expo-audio');
      } catch (modErr) {
        console.warn('[startRecording] expo-audio require failed:', modErr?.message);
        if (Platform.OS === 'android') {
          try {
            const { Alert } = require('react-native');
            Alert.alert(
              t('chatConv.audioModuleUnavailable') || 'Áudio indisponível',
              'O módulo de gravação não está disponível neste dispositivo.',
            );
          } catch {}
        }
        setError(t('chatConv.audioModuleUnavailable'));
        onCancel();
        return;
      }
      let perm;
      try {
        perm = await expoAudio.requestRecordingPermissionsAsync();
      } catch (permErr) {
        console.warn('[startRecording] permission request failed:', permErr?.message);
        if (Platform.OS === 'android') {
          try {
            const { Alert } = require('react-native');
            Alert.alert(
              t('chatConv.micPermissionDenied') || 'Permissão negada',
              'Habilite o microfone nas configurações do Android para gravar áudio.',
            );
          } catch {}
        }
        setError(t('chatConv.micPermissionDenied'));
        onCancel();
        return;
      }
      if (!perm?.granted) {
        if (Platform.OS === 'android') {
          try {
            const { Alert } = require('react-native');
            Alert.alert(
              t('chatConv.micPermissionDenied') || 'Permissão de microfone necessária',
              'Habilite o microfone nas configurações do Android para gravar áudio.',
            );
          } catch {}
        }
        setError(t('chatConv.micPermissionDenied'));
        onCancel();
        return;
      }
      if (!mountedRef.current) return;
      try {
        await expoAudio.setAudioModeAsync({ allowsRecording: true, playsInSilentMode: true });
      } catch (modeErr) {
        // Non-fatal on Android — some Android devices reject playsInSilentMode
        // but recording still works. Log and continue.
        console.warn('[startRecording] setAudioModeAsync failed:', modeErr?.message);
      }
      // ⭐ Native recorder (iOS AVAudioRecorder, Android MediaRecorder) — real
      // waveform samples + lower latency than expo-audio. Falls back to
      // expo-audio if the native module isn't installed (older binary).
      // [WAVE 39] On Android wrap native path in extra-defensive check —
      // expo-native-toolkit Android impl had a NPE on some devices when
      // startRecording fired before mic warmup.
      let nativeRec = null;
      if (Platform.OS === 'ios' || Platform.OS === 'android') {
        try {
          const { Audio: NativeAudio } = require('../modules/expo-native-toolkit');
          if (NativeAudio?.startRecording) {
            const path = await NativeAudio.startRecording();
            // [WAVE 39] Validate path returned is non-empty BEFORE wrapping the
            // recorder — empty/null path means native init silently failed and
            // we should fall back to expo-audio path instead of returning a
            // half-baked recorder object that crashes on stop().
            if (path && typeof path === 'string' && path.length > 0) {
              nativeRec = {
                __native: true, NativeAudio, path,
                stop: async () => {
                  try {
                    const result = await NativeAudio.stopRecording();
                    return result; // { path, durationMs, samples }
                  } catch (stopErr) {
                    console.warn('[NativeAudio.stop] failed:', stopErr?.message);
                    return null;
                  }
                },
              };
            }
          }
        } catch (nativeErr) {
          console.warn('[NativeAudio.startRecording] failed, falling back:', nativeErr?.message);
        }
      }
      let recorder = nativeRec;
      if (!recorder) {
        try {
          const AudioMod = require('expo-audio/build/AudioModule').default;
          const { RecordingPresets } = require('expo-audio');
          // [2026-09-23] Nota de voz não precisa de 128kbps estéreo 44.1k (HIGH_QUALITY):
          // voz é fala mono. Partimos do preset que funciona (mantém os enums de
          // outputFormat/encoder corretos por plataforma) e só baixamos os knobs
          // numéricos → arquivo ~4x menor, upload mais rápido, sem perda audível.
          const _base = RecordingPresets.HIGH_QUALITY || {};
          const VOICE_NOTE = {
            ..._base,
            sampleRate: 24000,
            numberOfChannels: 1,
            bitRate: 32000,
            // [2026-10-07 voice-native] live level for the UI-thread meter
            isMeteringEnabled: true,
            android: { ...(_base.android || {}) },
            ios: { ...(_base.ios || {}) },
            web: { ...(_base.web || {}), bitsPerSecond: 32000, mimeType: (_base.web && _base.web.mimeType) || 'audio/webm' },
          };
          recorder = new AudioMod.AudioRecorder(VOICE_NOTE);
        } catch (err) {
          console.warn('[startRecorder] Failed to load audio module:', err?.message);
          if (Platform.OS === 'android') {
            try {
              const { Alert } = require('react-native');
              Alert.alert(
                t('chatConv.audioModuleUnavailable') || 'Falha ao gravar áudio',
                'Não foi possível iniciar a gravação. Tente novamente.',
              );
            } catch {}
          }
          setError(t('chatConv.audioModuleUnavailable'));
          onCancel();
          return;
        }
      }
      if (!nativeRec) {
        try {
          await recorder.prepareToRecordAsync();
          recorder.record();
        } catch (recErr) {
          console.warn('[startRecorder] prepare/record failed:', recErr?.message);
          if (Platform.OS === 'android') {
            try {
              const { Alert } = require('react-native');
              Alert.alert(
                t('chatConv.recordingStartError') || 'Falha ao gravar áudio',
                'O microfone não respondeu. Reinicie o app e tente novamente.',
              );
            } catch {}
          }
          setError(t('chatConv.recordingStartError'));
          onCancel();
          return;
        }
      }
      if (!mountedRef.current) {
        try { await recorder.stop(); } catch {}
        // [2026-10-06 UX2] also drop the recording audio session (hold released early)
        try { await expoAudio.setAudioModeAsync({ allowsRecording: false }); } catch {}
        return;
      }
      setRecording(recorder);
      startTimer();
    } catch (e) {
      console.warn('Recording error:', e);
      // [WAVE 39] On Android surface the error as Alert so the user sees a clear
      // explanation instead of a silent banner that may be eaten by the keyboard.
      if (Platform.OS === 'android') {
        try {
          const { Alert } = require('react-native');
          Alert.alert(
            t('chatConv.recordingStartError') || 'Falha ao gravar áudio',
            e?.message || 'Não foi possível iniciar a gravação. Tente novamente.',
          );
        } catch {}
      }
      if (mountedRef.current) setError(t('chatConv.recordingStartError'));
      // [WAVE 39] If we crashed during start, bail out cleanly so the parent
      // doesn't keep AudioRecorder mounted in a broken state (white screen).
      try { onCancel(); } catch {}
    }
  };

  const stopWebRecorder = () => {
    return new Promise((resolve) => {
      const mr = mediaRecorderRef.current;
      if (!mr || mr.state === 'inactive') { resolve(); return; }
      mr.onstop = resolve;
      mr.stop();
    });
  };

  // STOP recording -> enter preview mode (WhatsApp-style: listen, then send or delete)
  const handleStop = async () => {
    if (!recording) return;
    recordingRef.current = null; // [2026-10-06 UX2] we own the stop now
    if (intervalRef.current) clearInterval(intervalRef.current);
    if (waveIntervalRef.current) clearInterval(waveIntervalRef.current);
    if (voiceDraftPersistRef.current) { clearInterval(voiceDraftPersistRef.current); voiceDraftPersistRef.current = null; }
    if (pulseLoopRef.current) pulseLoopRef.current.stop();
    // Notify others that recording stopped
    try {
      const tcpClient = require('../services/tcp-client').getTCPClient();
      tcpClient.sendStoppedRecording(conversationId);
    } catch {}
    try {
      if (Platform.OS === 'web') {
        await stopWebRecorder();
        const mr = mediaRecorderRef.current;
        if (mr?.stream) mr.stream.getTracks().forEach(t => t.stop());
        try { audioCtxRef.current?.close(); } catch {}
        if (chunksRef.current.length === 0) { onCancel(); return; }
        const blob = new Blob(chunksRef.current, { type: 'audio/webm' });
        const uri = URL.createObjectURL(blob);
        voiceDraftUriRef.current = uri;
        // Snapshot the captured waveform for preview rendering
        const snapshot = waveformLevels.slice(-60);
        // Final draft save with the real blob URI (in case the user kills the
        // app before tapping Send — recovery prompt will offer to restore).
        try {
          const AsyncStorage = require('@react-native-async-storage/async-storage').default;
          await AsyncStorage.setItem(
            'voice_draft:' + conversationId,
            JSON.stringify({ uri, duration, waveform: snapshot, type: 'audio/webm' })
          );
        } catch {}
        // Drain any pending pre-upload chunks before handing preview off so
        // that handleConfirmSend can call finalize without waiting on tail
        // bytes. Bounded by a 4 s safety timeout — if the server is wedged
        // we fall through to the legacy upload.
        if (voiceSessionRef.current?.alive) {
          await Promise.race([
            (async () => {
              while (
                voiceSessionRef.current?.alive &&
                (voiceUploadInflight.current || voiceUploadQueue.current.length > 0)
              ) {
                await drainVoiceUploadQueue();
                if (voiceUploadQueue.current.length === 0 && !voiceUploadInflight.current) break;
                await new Promise(r => setTimeout(r, 50));
              }
            })(),
            new Promise(r => setTimeout(r, 4000)),
          ]);
        }
        // View-once voice notes MUST go through the legacy chat_upload path
        // because chat_voice_session_finalize doesn't propagate the
        // view_once flag (it just dumps the assembled file into a row with
        // is_view_once=0). Skipping the session id forces the fallback
        // chatUploadFile branch in handleSendAudio, which forwards
        // view_once=1 to the server.
        const voiceSessionId = (voiceViewOnce || !voiceSessionRef.current?.alive)
          ? null
          : voiceSessionRef.current.sessionId;
        // Abandon the session server-side (GC will clean) when we skip it.
        if (voiceViewOnce && voiceSessionRef.current) {
          voiceSessionRef.current.alive = false;
        }
        setPreviewData({
          uri, blob,
          name: `audio_${Date.now()}.webm`,
          type: 'audio/webm',
          duration,
          waveform: snapshot,
          voiceSessionId, // null → legacy upload fallback (also used for view-once)
          voiceSessionMime: 'audio/webm',
          viewOnce: voiceViewOnce,
        });
      } else {
        let uri;
        let nativeWaveform = [];
        if (recording.__native) {
          // Native iOS recorder: stop() returns { path, durationMs, samples }
          const result = await recording.stop();
          const rawPath = result?.path || recording.path || '';
          // Ensure file:// prefix for React Native FormData upload
          uri = rawPath.startsWith('file://') ? rawPath : `file://${rawPath}`;
          // [2026-10-07 voice-native] 30 Hz meter samples → 40 peak bars for the
          // whole note (send path slices to 64 — raw samples meant the bubble
          // only showed the first ~2 s of the recording).
          nativeWaveform = resampleVoiceLevels(result?.samples || [], 40);
        } else {
          await recording.stop();
          uri = recording.uri;
        }
        try { const { setAudioModeAsync } = require('expo-audio'); await setAudioModeAsync({ allowsRecording: false }); } catch {}
        if (uri) {
          voiceDraftUriRef.current = uri;
          try {
            const AsyncStorage = require('@react-native-async-storage/async-storage').default;
            await AsyncStorage.setItem(
              'voice_draft:' + conversationId,
              JSON.stringify({ uri, duration, waveform: nativeWaveform, type: 'audio/mp4' })
            );
          } catch {}
          setPreviewData({ uri, name: `audio_${Date.now()}.m4a`, type: 'audio/mp4', duration, waveform: nativeWaveform, viewOnce: voiceViewOnce });
        } else {
          onCancel();
        }
      }
    } catch (e) {
      console.warn('Stop recording error:', e);
      try { const { setAudioModeAsync } = require('expo-audio'); await setAudioModeAsync({ allowsRecording: false }); } catch {}
      onCancel();
    }
    setRecording(null);
  };

  // Stop + send in one shot — wired to the primary Send (paper-plane) button on
  // the recorder pill. Flags the direct-send intent then runs the normal stop
  // pipeline; the previewData effect picks it up and confirms.
  const handleStopAndSend = () => {
    if (!recording) return;
    pendingDirectSendRef.current = true;
    handleStop();
  };

  // Clear persisted voice draft — call on send AND discard so we never
  // re-prompt for audio the user already resolved.
  const clearVoiceDraft = async () => {
    if (!conversationId) return;
    try {
      const AsyncStorage = require('@react-native-async-storage/async-storage').default;
      await AsyncStorage.removeItem('voice_draft:' + conversationId);
    } catch {}
  };

  // CONFIRM send from preview
  const handleConfirmSend = () => {
    if (!previewData) return;
    // Stop any preview playback
    try {
      if (Platform.OS === 'web' && previewAudioRef.current) {
        previewAudioRef.current.pause();
      }
    } catch {}
    if (previewIntervalRef.current) { clearInterval(previewIntervalRef.current); previewIntervalRef.current = null; }
    clearVoiceDraft();
    onSend(previewData);
  };

  // DELETE preview and exit
  const handleDeletePreview = () => {
    try { if (Platform.OS !== 'web') require('../services/haptics').warning(); } catch {}
    // Fully tear down the native/web preview player + restore mixWithOthers
    // so the deleted recording stops holding the audio session.
    teardownPreviewPlayer();
    if (previewData?.uri && Platform.OS === 'web') {
      try { URL.revokeObjectURL(previewData.uri); } catch {}
    }
    setPreviewData(null);
    setPreviewPlaying(false);
    setPreviewProgress(0);
    clearVoiceDraft();
    onCancel();
  };

  // PLAY/PAUSE preview
  const togglePreviewPlay = () => {
    if (!previewData) return;
    if (Platform.OS === 'web') {
      try {
        if (!previewAudioRef.current) {
          const audio = new window.Audio(previewData.uri);
          audio.onended = () => {
            setPreviewPlaying(false);
            setPreviewProgress(0);
            if (previewIntervalRef.current) { clearInterval(previewIntervalRef.current); previewIntervalRef.current = null; }
          };
          previewAudioRef.current = audio;
        }
        const audio = previewAudioRef.current;
        if (previewPlaying) {
          audio.pause();
          setPreviewPlaying(false);
          if (previewIntervalRef.current) { clearInterval(previewIntervalRef.current); previewIntervalRef.current = null; }
        } else {
          audio.play().catch(() => {});
          setPreviewPlaying(true);
          previewIntervalRef.current = setInterval(() => {
            if (!audio || !audio.duration) return;
            setPreviewProgress(audio.currentTime / audio.duration);
          }, 80);
        }
      } catch {}
    } else {
      // Native: use expo-audio AudioPlayer
      try {
        const { AudioModule } = require('expo-audio');
        if (!previewAudioRef.current) {
          const player = AudioModule?.default ? new AudioModule.default.AudioPlayer(previewData.uri) : null;
          previewAudioRef.current = player;
          // Drive the preview waveform from the player's playback clock —
          // MIRRORS the message-audio player at ~line 3040. Without this the
          // native preview played but previewProgress never moved, so the
          // bars sat frozen and the button stayed stuck on "playing" even
          // after the clip finished. Reset to Play + zero progress on end.
          try {
            if (player && typeof player.addListener === 'function') {
              const sub = player.addListener('playbackStatusUpdate', (s) => {
                if (!s) return;
                const dur = Number(s.duration) || 0;
                const cur = Number(s.currentTime) || 0;
                if (s.playing && dur > 0) {
                  setPreviewProgress(Math.max(0, Math.min(1, cur / dur)));
                }
                // Finished on its own → flip back to Play, rewind the bars.
                if (!s.playing && dur > 0 && cur >= dur - 0.05) {
                  setPreviewPlaying(false);
                  setPreviewProgress(0);
                  try { player.seekTo?.(0); } catch {}
                }
              });
              // Stash the subscription so teardown can remove it (leak fix).
              player._previewSub = sub;
            }
          } catch {}
        }
        const player = previewAudioRef.current;
        if (!player) return;
        if (previewPlaying) {
          player.pause?.();
          setPreviewPlaying(false);
        } else {
          player.play?.();
          setPreviewPlaying(true);
        }
      } catch {}
    }
  };

  // Tear down the native preview player + hand the audio session back to the
  // OS. Without this the AVAudioSession stayed grabbed after the user deleted
  // a recording, so Spotify/YouTube never resumed ("apaguei o áudio mas a
  // música não voltou"). MIRRORS the message-audio cleanup at ~2808-2824.
  const teardownPreviewPlayer = () => {
    if (previewIntervalRef.current) { clearInterval(previewIntervalRef.current); previewIntervalRef.current = null; }
    const p = previewAudioRef.current;
    if (!p) return;
    if (Platform.OS === 'web') {
      try { p.pause?.(); } catch {}
    } else {
      try { p._previewSub?.remove?.(); } catch {}
      try { p.pause?.(); } catch {}
      try { p.remove?.(); } catch {}
      // Release exclusivity so other apps' audio can resume (mixWithOthers).
      try {
        const { setAudioModeAsync } = require('expo-audio');
        setAudioModeAsync?.({
          interruptionMode: 'mixWithOthers',
          interruptionModeAndroid: 'mixWithOthers',
        }).catch(() => {});
      } catch {}
    }
    previewAudioRef.current = null;
  };

  const handleCancel = async () => {
    recordingRef.current = null; // [2026-10-06 UX2] we own the teardown now
    if (intervalRef.current) clearInterval(intervalRef.current);
    // Release the preview player + audio session too (covers cancelling
    // straight from the preview pill, not just an in-progress recording).
    teardownPreviewPlayer();
    // Kill any pending pre-upload session — discards the partial file
    // server-side via the GC cron (sessions older than 10 min get cleaned).
    // Future: a dedicated chat_voice_session_abort would clean immediately.
    if (voiceSessionRef.current) {
      voiceSessionRef.current.alive = false;
      voiceSessionRef.current = null;
    }
    voiceUploadQueue.current = [];
    if (Platform.OS === 'web') {
      try {
        await stopWebRecorder();
        const mr = mediaRecorderRef.current;
        if (mr?.stream) mr.stream.getTracks().forEach(t => t.stop());
      } catch {}
    } else if (recording && recording !== 'web') {
      if (recording.__native && recording.NativeAudio?.cancelRecording) {
        try { await recording.NativeAudio.cancelRecording(); } catch {}
      } else {
        try { await recording.stop(); } catch {}
      }
      try { const { setAudioModeAsync } = require('expo-audio'); await setAudioModeAsync({ allowsRecording: false }); } catch {}
    }
    setRecording(null);
    onCancel();
  };

  // Show error state instead of crashing
  if (error) {
    return (
      <View style={[recStyles.container, { backgroundColor: colors.surface, borderTopColor: colors.border }]}>
        <View style={recStyles.errorInner}>
          <IconAlertTriangle size={18} color={colors.error || '#ef4444'} />
          <Text style={[recStyles.errorText, { color: colors.error || '#ef4444' }]}>{error}</Text>
        </View>
        <TouchableOpacity onPress={onCancel} style={recStyles.iconBtn} accessibilityLabel={t('chatConv.cancelRecording') || 'Cancelar gravação'}>
          <IconX size={20} color={colors.textSecondary} />
        </TouchableOpacity>
      </View>
    );
  }

  const isDarkBg = colors.surface === '#1e1e1e' || colors.surface === '#121212' || colors.surface === '#000';
  const recBg = isDarkBg ? 'rgba(17, 17, 17,0.08)' : 'rgba(17, 17, 17,0.06)';
  const previewBg = isDarkBg ? 'rgba(17, 17, 17,0.10)' : 'rgba(17, 17, 17,0.08)';
  const waveColor = '#111111';
  const slideCancelColor = colors.textSecondary;

  // ─── [2026-10-06 UX2] HOLD-TO-RECORD controller ───
  // Re-assigned every render so it always closes over the live `recording`.
  latestRef.current = { handleCancel, handleStop, handleStopAndSend };
  if (holdCtlRef) {
    holdCtlRef.current = {
      move: ({ dx = 0 } = {}) => {
        if (holdTrashing) return;
        slideX.setValue(Math.max(Math.min(0, dx), -140));
      },
      cancel: () => {
        // WhatsApp: the mic drops into a trash can, then the pill closes.
        setHoldTrashing(true);
        try { if (Platform.OS !== 'web') require('../services/haptics').tap('heavy'); } catch {}
        if (isReduceMotionEnabled()) { handleCancel(); return; }
        trashAnim.setValue(0);
        Animated.timing(trashAnim, { toValue: 1, duration: 380, easing: Easing.out(Easing.cubic), useNativeDriver: true })
          .start(() => { handleCancel(); });
      },
      lock: () => {
        Animated.spring(slideX, { toValue: 0, tension: 220, friction: 14, useNativeDriver: false }).start();
      },
      release: () => {
        const elapsed = startTimeRef.current ? Date.now() - startTimeRef.current : 0;
        if (!recording || elapsed < 1000) {
          // Too short (or recorder still warming up) → discard + teach the gesture.
          try { onShortHold?.(); } catch {}
          handleCancel();
          return;
        }
        handleStopAndSend();
      },
    };
  }

  if (holdMode === 'hold' && !previewData) {
    const holdHintOpacity = slideX.interpolate({ inputRange: [-120, 0], outputRange: [0.15, 1], extrapolate: 'clamp' });
    const trashScale = trashAnim.interpolate({ inputRange: [0, 0.4, 1], outputRange: [0.6, 1.25, 0.2] });
    const trashRotate = trashAnim.interpolate({ inputRange: [0, 0.4, 1], outputRange: ['0deg', '-14deg', '0deg'] });
    const trashOpacity = trashAnim.interpolate({ inputRange: [0, 0.75, 1], outputRange: [1, 1, 0] });
    return (
      <View style={[recStyles.holdPill, { backgroundColor: recBg }]}>
        <View style={recStyles.holdLeft}>
          {holdTrashing ? (
            <Animated.View style={{ width: 24, alignItems: 'center', opacity: trashOpacity, transform: [{ scale: trashScale }, { rotate: trashRotate }] }}>
              <IconTrash size={22} color={colors.error || '#ef4444'} />
            </Animated.View>
          ) : (
            <View style={recStyles.dotOuter}>
              <Animated.View style={[recStyles.dotRing, { transform: [{ scale: pulseAnim }] }]} />
              <View style={recStyles.dotCore} />
            </View>
          )}
          <Text style={[recStyles.timer, { color: colors.text, marginLeft: 8 }]}>{formatDuration(duration)}</Text>
        </View>
        <Animated.View
          style={[recStyles.holdHintRow, { opacity: holdTrashing ? 0 : holdHintOpacity, transform: [{ translateX: slideX }] }]}
          accessibilityLiveRegion="polite"
        >
          <IconChevronLeft size={16} color={slideCancelColor} />
          <Text style={[recStyles.slideHint, { color: slideCancelColor }]} numberOfLines={1}>
            {t('chatConv.slideToCancel') || 'Deslize para cancelar'}
          </Text>
        </Animated.View>
      </View>
    );
  }

  // ─── PREVIEW MODE (after stopping recording, before sending) ───
  if (previewData) {
    const previewWaveform = previewData.waveform && previewData.waveform.length > 0
      ? previewData.waveform
      : Array.from({ length: 36 }, () => 0.2 + Math.random() * 0.7);
    const playedBars = Math.floor(previewProgress * previewWaveform.length);
    return (
      <View style={[recStyles.container, recStyles.previewPill, { backgroundColor: previewBg, borderTopColor: colors.border }]}>
        {/* Delete button */}
        <TouchableOpacity onPress={handleDeletePreview} style={recStyles.iconBtn} accessibilityLabel="Apagar gravação">
          <View style={recStyles.trashWrap}>
            <IconTrash size={20} color={colors.error || '#ef4444'} />
          </View>
        </TouchableOpacity>

        {/* Play / Pause */}
        <TouchableOpacity onPress={togglePreviewPlay} style={recStyles.previewPlayBtn} accessibilityLabel={previewPlaying ? 'Pausar' : 'Reproduzir'}>
          {previewPlaying
            ? <IconPause size={20} color="#fff" />
            : <IconPlay size={20} color="#fff" />}
        </TouchableOpacity>

        {/* Static waveform with played-progress overlay */}
        <View style={[recStyles.waveform, { marginLeft: 4 }]}>
          {previewWaveform.slice(0, 36).map((level, i) => {
            const played = i < playedBars;
            return (
              <View
                key={i}
                style={[
                  recStyles.waveBar,
                  {
                    height: Math.max(4, level * 30),
                    backgroundColor: played ? '#111111' : (isDarkBg ? '#2c2c2e' : '#9ca3af'),
                    opacity: played ? 1 : 0.55,
                  },
                ]}
              />
            );
          })}
        </View>

        {/* Duration */}
        <Text style={[recStyles.timer, { color: colors.text, marginLeft: 8, marginRight: 8 }]}>
          {formatDuration(previewData.duration || duration)}
        </Text>

        {/* View-once toggle on preview — last chance to flip before sending.
            Mirrors the toggle on the record pill so users who only decide to
            mark "view-once" *after* listening back can still flip the flag.
            Tapping updates previewData.viewOnce which handleConfirmSend
            forwards to handleSendAudio. */}
        <TouchableOpacity
          onPress={() => setPreviewData(p => p ? { ...p, viewOnce: !p.viewOnce } : p)}
          style={[
            recStyles.voiceOnceBtn,
            previewData.viewOnce ? recStyles.voiceOnceBtnActive : { borderColor: colors.border || 'rgba(17, 17, 17,0.35)' },
          ]}
          accessibilityRole="button"
          accessibilityLabel={previewData.viewOnce ? (t('chatConv.viewOnceVoiceLabel') || 'Áudio único') : 'Marcar como visualização única'}
        >
          <Text style={[recStyles.voiceOnceBtnText, { color: previewData.viewOnce ? '#fff' : (colors.textTertiary || '#9ca3af') }]}>1</Text>
        </TouchableOpacity>

        {/* Send */}
        <TouchableOpacity onPress={handleConfirmSend} style={recStyles.sendBtn} accessibilityLabel={t('chatConv.sendAudio') || 'Enviar áudio'}>
          <IconSend size={20} color="#fff" />
        </TouchableOpacity>
      </View>
    );
  }

  // ─── RECORDING MODE ───
  // PanResponder for WhatsApp / Telegram-style slide-to-cancel. Horizontal drag
  // past -80px cancels; the pill follows the finger horizontally. (Slide-up-to-
  // lock was removed — this recorder is tap-to-record/hands-free already, so a
  // lock affordance is redundant. Cancel is also always reachable via the X.)
  const slideCancelPan = PanResponder.create({
    onStartShouldSetPanResponder: () => false,
    onMoveShouldSetPanResponder: (_, g) => Math.abs(g.dx) > 10,
    onPanResponderGrant: () => { slideHapticRef.current = false; },
    onPanResponderMove: (_, g) => {
      if (g.dx < 0) {
        slideX.setValue(Math.max(g.dx, -140));
      }
      // Haptic tick when crossing the cancel threshold (and again when
      // coming back) so the user feels the "point of no return".
      const past = g.dx < -80;
      if (past !== slideHapticRef.current) {
        slideHapticRef.current = past;
        try { if (Platform.OS !== 'web') require('../services/haptics').tap(past ? 'medium' : 'light'); } catch {}
      }
    },
    onPanResponderRelease: (_, g) => {
      if (g.dx < -80 || g.vx < -0.6) {
        // Snap the pill further off-screen then cancel — the user sees the
        // slide complete rather than the pill just disappearing at release.
        // useNativeDriver MUST be false: slideX simultaneously drives the
        // container `translateX` AND is interpolated into `opacity` props
        // (slideHintOpacity/cancelHintOpacity below). On Android, committing
        // slideX to the native driver while it also feeds a JS-only `opacity`
        // throws a fatal "native animated node" error the instant the record
        // pill mounts — i.e. the moment recording starts. Keeping it JS-driven
        // lets one value safely power both transform and opacity.
        try { if (Platform.OS !== 'web') require('../services/haptics').warning(); } catch {}
        Animated.timing(slideX, { toValue: -200, duration: 160, useNativeDriver: false }).start(() => {
          cancelledRef.current = true;
          handleCancel();
        });
      } else {
        Animated.spring(slideX, { toValue: 0, tension: 220, friction: 14, useNativeDriver: false }).start();
      }
    },
  });
  const slideHintOpacity = slideX.interpolate({ inputRange: [-100, 0], outputRange: [0, 1] });
  // Cancel hint (left) — slides slightly left + fades as the user drags. Matches
  // the spec: translateX -30 → 0 across the -100..0 range, opacity ramps in
  // (0 → 0.5 → 1) so the affordance is loudest when the finger is at rest.
  const cancelHintTranslateX = slideX.interpolate({ inputRange: [-100, 0], outputRange: [-30, 0], extrapolate: 'clamp' });
  const cancelHintOpacity = slideX.interpolate({ inputRange: [-100, -50, 0], outputRange: [0, 0.5, 1], extrapolate: 'clamp' });

  return (
    <Animated.View
      style={[recStyles.container, recStyles.recordPill, { backgroundColor: recBg, borderTopColor: colors.border, transform: [{ translateX: slideX }] }]}
      {...slideCancelPan.panHandlers}
    >
      {/* Left: cancel (X) — discards the recording. Always available so the
          user has a clear way out regardless of the slide-to-cancel gesture. */}
      <TouchableOpacity onPress={() => { try { if (Platform.OS !== 'web') require('../services/haptics').warning(); } catch {} handleCancel(); }} style={recStyles.iconBtn} accessibilityLabel={t('chatConv.cancelRecording') || 'Cancelar gravação'}>
        <View style={recStyles.trashWrap}>
          <IconX size={20} color={colors.error || '#ef4444'} />
        </View>
      </TouchableOpacity>

      {/* Center: dot + timer + waveform + slide hint */}
      <View style={recStyles.centerCol}>
        <View style={recStyles.topRow}>
          {/* Pulsing red dot */}
          <View style={recStyles.dotOuter}>
            <Animated.View style={[recStyles.dotRing, { transform: [{ scale: pulseAnim }] }]} />
            <View style={recStyles.dotCore} />
          </View>

          {/* Timer — color shifts as the recording gets long, so the user gets
              a passive "wrap it up" cue without any banner. <60s text, 60-120s
              amber, >120s red (matches WhatsApp's intuitive feedback). */}
          <Text style={[recStyles.timer, {
            color: duration >= 120 ? '#ef4444' : duration >= 60 ? '#f59e0b' : colors.text,
          }]}>{formatDuration(duration)}</Text>

          {/* [2026-10-07 voice-native] Native: live input level on the UI thread
              (VoiceLiveMeter — Reanimated shared value, no React render per
              sample). Web keeps the AnalyserNode bars below. */}
          {Platform.OS !== 'web' ? (
            <VoiceLiveMeter getLevel={getLiveLevel} active={!!recording} color={waveColor} />
          ) : (
            // Web live waveform — bars breathe in sync with the recording-dot
            // pulse, giving the whole control a single coherent heartbeat.
            <View style={recStyles.waveform}>
              {waveformLevels.length === 0
                ? Array.from({ length: 28 }).map((_, i) => (
                    <Animated.View key={i} style={[recStyles.waveBar, {
                      height: 4,
                      backgroundColor: waveColor,
                      opacity: pulseAnim.interpolate({ inputRange: [1, 1.6], outputRange: [0.22, 0.42] }),
                    }]} />
                  ))
                : waveformLevels.slice(-28).map((level, i) => (
                    <Animated.View
                      key={i}
                      style={[
                        recStyles.waveBar,
                        {
                          height: Math.max(4, level * 34),
                          backgroundColor: waveColor,
                          opacity: pulseAnim.interpolate({
                            inputRange: [1, 1.6],
                            outputRange: [Math.max(0.4, 0.45 + level * 0.4), Math.min(1, 0.7 + level * 0.3)],
                          }),
                        },
                      ]}
                    />
                  ))
              }
            </View>
          )}
        </View>

        {/* Slide hint — two states:
            • view-once engaged → show the view-once explainer in purple
            • default → IconChevronLeft + "Deslize para cancelar"; the chevron
              slides slightly left + fades as the finger drags, with the
              translateX/opacity interpolations spec'd by the design. */}
        <Animated.View style={[recStyles.slideRow, { opacity: slideHintOpacity }]}>
          {voiceViewOnce ? (
            <Text style={[recStyles.slideHint, { color: '#111111', fontWeight: '600' }]} numberOfLines={1}>
              {t('chatConv.viewOnceVoiceHint') || 'Áudio só pode ser ouvido uma vez'}
            </Text>
          ) : (
            <Animated.View style={{
              flexDirection: 'row',
              alignItems: 'center',
              gap: 4,
              transform: [{ translateX: cancelHintTranslateX }],
              opacity: cancelHintOpacity,
            }}>
              <IconChevronLeft size={14} color={slideCancelColor} />
              <Text style={[recStyles.slideHint, { color: slideCancelColor }]}>
                {t('chatConv.slideToCancel') || 'Deslize para cancelar'}
              </Text>
            </Animated.View>
          )}
        </Animated.View>
      </View>

      {/* View-once "1" toggle — WhatsApp 2026-Q1 parity. Tapping flips the
          flag; sending this voice note will deliver as is_view_once=1 and
          the recipient bubble plays exactly once before locking. Visual:
          small pill, dim border when off, solid purple when on. Hint text
          ("Áudio só pode ser ouvido uma vez") appears under the slide-to-
          cancel row when active so the user has explicit confirmation. */}
      <TouchableOpacity
        onPress={() => setVoiceViewOnce(v => !v)}
        style={[
          recStyles.voiceOnceBtn,
          voiceViewOnce ? recStyles.voiceOnceBtnActive : { borderColor: colors.border || 'rgba(17, 17, 17,0.35)' },
        ]}
        accessibilityRole="button"
        accessibilityLabel={voiceViewOnce ? (t('chatConv.viewOnceVoiceLabel') || 'Áudio único') : 'Marcar como visualização única'}
      >
        <Text style={[recStyles.voiceOnceBtnText, { color: voiceViewOnce ? '#fff' : (colors.textTertiary || '#9ca3af') }]}>1</Text>
      </TouchableOpacity>
      {/* Right controls — hands-free: an explicit Stop-to-preview button PLUS a
          primary purple Send button, with a "Toque para enviar" hint above.
          This recorder is tap-to-record, so the finger is already free: a clear
          Stop + Send pair is always shown (no lock state). */}
      <View style={recStyles.lockedActions}>
        <View pointerEvents="none" style={recStyles.tapToSendHint}>
          <Text style={recStyles.tapToSendHintText} numberOfLines={1}>
            {t('chatConv.tapToSend') || 'Toque para enviar'}
          </Text>
        </View>
        {/* Stop → preview (review before sending) */}
        <TouchableOpacity
          onPress={handleStop}
          style={recStyles.lockedStopBtn}
          accessibilityLabel={t('chatConv.stopAndPreview') || 'Parar e pré-ouvir'}
          hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
        >
          <View style={recStyles.stopSquare} />
        </TouchableOpacity>
        {/* Send → ship the recorded audio immediately */}
        <TouchableOpacity
          onPress={handleStopAndSend}
          style={recStyles.lockedSendBtn}
          accessibilityLabel={t('chatConv.sendAudio') || 'Enviar áudio'}
          hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
        >
          <IconSend size={20} color="#fff" />
        </TouchableOpacity>
      </View>
    </Animated.View>
  );
}

