          isGroup: isGroupConv,
          peerReadWatermark: readWatermark,
          peerDeliveredWatermark: isGroupConv ? -1 : deliveredWatermark,
          peerReadAt: !isGroupConv && (item.read_at || _peerReadOnLoad(item)),
          peerDelivered: albumPeerDelivered,
